INSERT INTO resource_cloud_migration_audit(run_id,owner_type,resource_id,source_identity,content_generation,old_values,disposition,created_at)
SELECT CONCAT('alias:',old.id,':',canonical.id),'album',old.id,SHA2(CAST(JSON_ARRAY('album_alias',old.id,canonical.id) AS CHAR),256),old.content_generation,
 JSON_OBJECT('canonical_resource_id',canonical.id,'source_ref_id',old.album_source_ref_id,'source_revision',old.source_revision,'local_path',old.local_path,'checksum',old.checksum,'size_bytes',old.size_bytes,'reference_sha256',old.reference_sha256,'reference_size_bytes',old.reference_size_bytes,'local_content_generation',old.local_content_generation,'local_target_revision',old.local_target_revision,'local_skip_generation',old.local_skip_generation,'local_skip_target_revision',old.local_skip_target_revision,'local_skip_baseline',old.local_skip_baseline,'local_skip_reason',old.local_skip_reason,
 'retired_cloud_archive',(SELECT retired.old_values FROM resource_cloud_migration_audit retired WHERE retired.run_id='schema-retirement-v2026102913' AND retired.owner_type='album' AND retired.resource_id=old.id AND retired.disposition='archived'),
 'baseline_block',(SELECT JSON_OBJECT('baseline_id',b.baseline_id,'reason',b.reason) FROM resource_baseline_blocks b WHERE b.owner_type='album' AND b.resource_id=old.id AND b.content_generation=old.content_generation),
 'cloud_receipts',(SELECT JSON_ARRAYAGG(JSON_OBJECT('provider',c.cloud_provider,'path',c.cloud_path,'checksum',c.checksum,'size_bytes',c.size_bytes,'content_generation',c.content_generation,'target_revision',c.target_revision,'confirmed_content_generation',c.confirmed_content_generation,'confirmed_target_revision',c.confirmed_target_revision,'verification',c.verification,'verification_method',c.verification_method,'remote_hash_algorithm',c.remote_hash_algorithm,'remote_hash_value',c.remote_hash_value,'uploaded_at',c.uploaded_at,'verified_at',c.verified_at,'adapter',c.source_adapter,'evidence',c.evidence,'transfer_policy',c.transfer_policy,'policy_content_generation',c.policy_content_generation,'policy_target_revision',c.policy_target_revision,'baseline_id',c.baseline_id,'skip_reason',c.skip_reason,'path_unresolved',c.path_unresolved)) FROM resource_cloud_receipts c WHERE c.owner_type='album' AND c.resource_id=old.id)),
 'alias_retired',UNIX_TIMESTAMP()
FROM album_resources old JOIN album_resources canonical ON canonical.album_source_ref_id=? AND canonical.resource_kind=old.resource_kind
WHERE old.album_source_ref_id=? AND (EXISTS(SELECT 1 FROM resource_cloud_migration_audit retired WHERE retired.run_id='schema-retirement-v2026102913' AND retired.owner_type='album' AND retired.resource_id=old.id AND retired.disposition='archived') OR old.local_skip_generation>0 OR old.reference_sha256<>'' OR EXISTS(SELECT 1 FROM resource_cloud_receipts c WHERE c.owner_type='album' AND c.resource_id=old.id) OR EXISTS(SELECT 1 FROM resource_baseline_blocks b WHERE b.owner_type='album' AND b.resource_id=old.id AND b.content_generation=old.content_generation))
